sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float radius;
uniform float feather;
uniform float roundness;
layout(color) uniform half4 vigColor;
uniform float amount;
uniform float blend;
uniform float exposure;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 p = (coord / size - center) * float2(mix(1.0, size.x / size.y, roundness), 1.0) * 2.0;
    float v = smoothstep(radius, radius + feather, length(p));
    float3 base = s * (1.0 + exposure * (1.0 - v));
    float3 o = mix(base, blendm(base, float3(vigColor.rgb), blend), v * amount);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
